import 'package:flutter/material.dart';
import 'core/app_config.dart';
import 'services/supabase_service.dart';
import 'services/auth_service.dart';
import 'services/account_service.dart';
import 'screens/login_screen.dart'; import 'screens/register_screen.dart'; import 'screens/onboarding_screen.dart'; import 'screens/connections_screen.dart';
import 'screens/home_screen.dart'; import 'screens/unified_modules.dart'; import 'screens/create_post_screen.dart'; import 'screens/profile_screen.dart';
import 'screens/opportunities_screen.dart'; import 'screens/notifications_screen.dart'; import 'screens/search_screen.dart'; import 'screens/safety_screen.dart'; import 'screens/verification_screen.dart'; import 'screens/privacy_settings_screen.dart'; import 'screens/admin_dashboard_screen.dart'; import 'screens/notification_preferences_screen.dart';
Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await SupabaseService.init(); runApp(const AfricaLinkApp()); }
class AfricaLinkApp extends StatelessWidget { const AfricaLinkApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:AppConfig.appName,debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.green),initialRoute:'/gate',routes:{'/gate':(_)=>const AuthGate(),'/login':(_)=>const LoginScreen(),'/register':(_)=>const RegisterScreen(),'/onboarding':(_)=>const OnboardingScreen(),'/home':(_)=>const AppShell(index:0),'/explore':(_)=>const AppShell(index:1),'/create':(_)=>const CreatePostScreen(),'/profile':(_)=>const ProfileScreen(),'/opportunities':(_)=>const OpportunitiesScreen(),'/notifications':(_)=>const NotificationsScreen(),'/search':(_)=>const SearchScreen(),'/safety':(_)=>const SafetyScreen(),'/verification':(_)=>const VerificationScreen(),'/connections':(_)=>const ConnectionsScreen(),'/privacy':(_)=>const PrivacySettingsScreen(),'/admin':(_)=>const AdminDashboardScreen(),'/notification-settings':(_)=>const NotificationPreferencesScreen()}); }
class AuthGate extends StatelessWidget { const AuthGate({super.key}); @override Widget build(BuildContext c){if(!AppConfig.configured)return const Scaffold(body:Center(child:Padding(padding:EdgeInsets.all(24),child:Text('Configure SUPABASE_URL and SUPABASE_ANON_KEY to run AFRICA LINK.'))));return StreamBuilder(stream:AuthService().authState,builder:(c,s){final u=AuthService().user;if(u==null)return const LoginScreen();return FutureBuilder<bool>(future:AccountService().hasProfile(),builder:(c,p)=>p.connectionState!=ConnectionState.done?const Scaffold(body:Center(child:CircularProgressIndicator())):(p.data==true?const AppShell(index:0):const OnboardingScreen()));});}}
class AppShell extends StatefulWidget { final int index; const AppShell({super.key,this.index=0}); @override State<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends State<AppShell>{late int i; final pages=const [HomeScreen(),UnifiedModules(),SizedBox.shrink(),OpportunitiesScreen(),ProfileScreen()]; @override void initState(){super.initState();i=widget.index;}
void go(int n){if(n==2){Navigator.pushNamed(context,'/create');return;}setState(()=>i=n);} @override Widget build(BuildContext c)=>Scaffold(body:pages[i],bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:go,destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.explore_outlined),selectedIcon:Icon(Icons.explore),label:'Explore'),NavigationDestination(icon:Icon(Icons.add_circle_outline),selectedIcon:Icon(Icons.add_circle),label:'Create'),NavigationDestination(icon:Icon(Icons.work_outline),selectedIcon:Icon(Icons.work),label:'Opportunities'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Profile')]));}
